"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type RipplePrimitiveProps = ComponentProps<typeof motion.div>;

export function RipplePrimitive({ children, ...props }: RipplePrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      whileTap={reduceMotion ? undefined : {scale: 0.98}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.16, ease: [0.23, 1, 0.32, 1] }}
    >
      {children}
    </motion.div>
  );
}
